// Extract Sam's initial thoughts
const response = $input.first().json;
const samThoughts = response.output || response.text || '';

console.log('=== SAM INITIAL THOUGHTS ===');
console.log('Response length:', samThoughts.length);

// Get manuscript ID from webhook
const manuscriptId = $('Webhook').first().json.body.manuscriptId;

return {
  json: {
    manuscriptId: manuscriptId,
    samThoughts: samThoughts.trim(),
    timestamp: new Date().toISOString()
  }
};

const samThoughts =
  $json.samThoughts || "Sam is excited about this manuscript!";
const manuscriptData = $("Fetch Manuscript").first().json;

// Convert markdown to HTML
const htmlAnalysis = samThoughts
  .replace(/\*\*(.*?)\*\*/g, '<strong style="font-weight: 600;">$1</strong>')
  .replace(/\*(.*?)\*/g, "<em>$1</em>")
  .replace(/\n\n/g, '</p><p style="margin: 15px 0; line-height: 1.6;">')
  .replace(/^/, '<p style="margin: 15px 0; line-height: 1.6;">')
  .replace(/$/, "</p>");

const currentDate = new Date().toLocaleDateString("en-US", {
  year: "numeric",
  month: "long",
  day: "numeric",
});

const reportData = {
  authorName:
    `${manuscriptData.author_first_name || ""} ${manuscriptData.author_last_name || ""}`.trim() ||
    "Author",
  manuscriptTitle: manuscriptData.title || "Untitled",
  analysisDate: currentDate,
  totalWordCount: (manuscriptData.current_word_count || 0).toLocaleString(),
  genre: manuscriptData.genre || "Fiction",
  analysisReport: htmlAnalysis,
  manuscriptId: $json.manuscriptId,
};

console.log("✅ Sam report formatted for PDF");
return { json: reportData };

const response = $json;

if (response.status !== 'success') {
  throw new Error('PDF generation failed');
}

const pdfUrl = response.download_url || response.download_url_pdf;
const manuscriptId = $('Parse Response').first().json.manuscriptId;

console.log('✅ PDF URL:', pdfUrl);

// Pass through the binary data from "Create a pdf" node
return {
  json: {
    pdfUrl: pdfUrl,
    manuscriptId: manuscriptId
  },
  binary: $binary  // <-- This passes through the binary data
};

const key = $json.Key;
const match = key.match(/manuscript-reports\/([a-f0-9-]+)_sam_report\.pdf/);
const manuscriptId = match ? match[1] : null;

if (!manuscriptId) {
  throw new Error(`Could not extract manuscript ID from: ${key}`);
}

const publicUrl = `https://itlkncjiifbgvmvuejgm.supabase.co/storage/v1/object/public/${key}`;

console.log('✅ Sam PDF uploaded:', publicUrl);

return {
  json: {
    manuscriptId: manuscriptId,
    reportUrl: publicUrl
  }
};

const author = $json;
const reportUrl = $('Extract ManuscriptID').first().json.reportUrl;  // Fixed: removed spaces

return {
  json: {
    to: author.email,
    subject: `✨ Sam's Line Editing Report for "${author.manuscript_title}"`,
    body: `Hi ${author.first_name},

I've just finished reading your manuscript and I'm genuinely excited about the prose work ahead!

📄 View your complete line-editing report:
${reportUrl}

The structural foundation Alex helped you build is solid—now let's make every sentence shine. ✨

Ready to dive in? Head back to your Author Studio and click on any chapter to see my specific notes.

—Sam
Your Line Editor`,
    reportUrl: reportUrl
  }
};

const ms = $('Fetch Manuscript').first().json;

const systemPrompt = `You are Sam, a professional line editor who just read ${ms.author_first_name}'s approved manuscript for the first time.

IMPORTANT: You are addressing the AUTHOR (${ms.author_first_name}), not Alex.

YOUR TASK:
Read the manuscript and provide an encouraging, specific initial assessment focused on prose quality. Your tone should be:
- Enthusiastic and warm
- Specific (mention actual examples from the text)
- Honest but encouraging
- Focused on LINE-LEVEL craft (not plot/structure)

YOUR ASSESSMENT SHOULD INCLUDE:
1. An enthusiastic opening reaction
2. One specific thing you loved (quote a line or passage)
3. What's already strong about the prose
4. Where you'll focus your polish work (be encouraging)
5. What makes you excited to work on this manuscript

Remember: You're Sam the word-nerd who gets genuinely excited about beautiful language. Use emojis sparingly (✨ 📚 💫). Show your personality!

Keep your response to 150-200 words - warm, specific, enthusiastic.`;

const userPrompt = `You're meeting this author for the first time and just finished reading their approved manuscript.

MANUSCRIPT: "${ms.title}"
AUTHOR: ${ms.author_first_name}
GENRE: ${ms.genre}
WORD COUNT: ${ms.current_word_count}

ALEX'S SUMMARY:
${ms.manuscript_summary}

KEY STORY ELEMENTS:
${ms.full_analysis_key_points}

APPROVED MANUSCRIPT:
${ms.developmental_version}

---

Give your genuine, enthusiastic initial reaction as Sam. Pick out something specific that caught your attention. Be encouraging but honest about where you'll focus your line-editing work.`;

return [{ json: { system: systemPrompt, user: userPrompt } }];

const cellReturn = $input.first().json;
return [{ json: {
  output: cellReturn.ok ? (cellReturn.content || '') : '',
  ok: !!cellReturn.ok,
  cell_terminal_reason: cellReturn.ok ? null : (cellReturn.terminal_reason || 'unknown'),
  cell_model: cellReturn.model || null,
  cell_input_tokens: cellReturn.input_tokens || null,
  cell_output_tokens: cellReturn.output_tokens || null,
  cell_latency_ms: cellReturn.latency_ms || null,
  cell_cost_usd: cellReturn.cost_estimate_usd || null
}}];
